Object.assign(SNIP,{});PRESET_NOTES["l62"]={"Ví dụ: Dựng cây phân đoạn tổng": "t[1] = 36 là tổng cả mảng; t[2] = 21 (nửa trái 5 2 8 6), t[3] = 15; t[4] = 7, t[5] = 14, … các lá t[8 … 15] chính là mảng a. Theo dõi cây lời gọi: build chia đôi tới lá rồi cộng ngược lên.", "Ví dụ: Truy vấn tổng trên đoạn": "Đoạn [2, 6] được ghép từ các nút nằm trọn bên trong: [2, 3] (t = 14), [4, 5] (t = 10), [6, 6] (t = 1). Kết quả 25. Cây lời gọi cho thấy nhánh ngoài đoạn trả về 0 ngay, nhánh nằm trọn trả t[i] ngay, chỉ hai mép phải đi sâu.", "Ví dụ: Cập nhật một phần tử": "Chỉ các nút trên đường từ gốc tới lá của vị trí 3 thay đổi: t[11] (lá), t[5], t[2], t[1]. Tổng cả mảng 30, tổng [2, 6] thành 19.", "Ví dụ: Cây min kèm vị trí": "Nút lưu cặp (giá trị, vị trí); phép ghép là min của cặp. Trên [1, 5] giá trị nhỏ nhất 2 xuất hiện ở vị trí 1 và 3; so cặp chọn vị trí nhỏ hơn: 1. Đổi phép ghép là đổi bài toán.", "Lỗi: cấp mảng 2n ô": "Với n = 6 cây không đầy: nút 13 (quản lý [4, 4]) có số hiệu vượt 2n = 12, ghi ra ngoài mảng. Trình mô phỏng dừng ngay; máy thật có thể in đúng, in sai hoặc sập tùy may rủi. Luôn cấp 4n ô."};EX_HINTS["l62"]=[["Cây min: t[i] = min(t[2i], t[2i + 1]); nút ngoài đoạn trả về +∞ (phần tử trung hòa của min).", "Đầu vào đánh số từ 1: trừ 1 trước khi gọi update/query trên đoạn [0, n − 1].", "Cây Fenwick không làm được min với thao tác gán tùy ý; bảng thưa không cập nhật được."], ["Mỗi nút lưu cặp (độ cao lớn nhất, vị trí). Phép ghép chọn cặp có độ cao lớn hơn; bằng nhau thì vị trí nhỏ hơn.", "Mẹo với pair của C++: lưu −vị trí thì max của cặp tự ưu tiên vị trí nhỏ khi độ cao bằng nhau.", "Nút ngoài đoạn trả về cặp có độ cao −∞."], ["Dùng cây max. Nếu t[gốc] < x thì không phòng nào đủ.", "Đi xuống: ở nút i, nếu max của con trái ≥ x thì đáp án nằm bên trái (vì muốn vị trí nhỏ nhất); không thì sang phải. Mỗi tầng một bước: O(log n).", "Duyệt từ đầu mảng tìm phòng đầu tiên tốn O(n) mỗi câu hỏi."]];
/* ===================== BÀI 62 · Cây phân đoạn (segment tree) ===================== */
/* Bài 62 · Cây phân đoạn (segment tree)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR62=[{label:"Ví dụ: Dựng cây phân đoạn tổng",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvector<int> a;\nvector<long long> t;\n\nvoid build(int i, int l, int r) {\n    if (l == r) { t[i] = a[l]; return; }\n    int m = (l + r) / 2;\n    build(2 * i, l, m);\n    build(2 * i + 1, m + 1, r);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {   // tổng trên [x, y]\n    if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n    if (x <= l && r <= y) return t[i];                 // nằm trọn\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nvoid update(int i, int l, int r, int p, int v) {      // a[p] = v\n    if (l == r) { t[i] = v; return; }\n    int m = (l + r) / 2;\n    if (p <= m) update(2 * i, l, m, p, v);\n    else update(2 * i + 1, m + 1, r, p, v);\n    t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n}\n\nint main() {\n    a = {5, 2, 8, 6, 3, 7, 1, 4};\n    int n = a.size();\n    t.assign(4 * n, 0);\n    build(1, 0, n - 1);\n    for (int i = 1; i < 16; i++) cout << t[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"calls"}],py:{code:"def build(i, l, r):\n    if l == r:\n        t[i] = a[l]\n        return\n    m = (l + r) // 2\n    build(2 * i, l, m)\n    build(2 * i + 1, m + 1, r)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):              # tổng trên [x, y]\n    if y < l or r < x:                 # ngoài: phần tử trung hòa\n        return 0\n    if x <= l and r <= y:              # nằm trọn\n        return t[i]\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\ndef update(i, l, r, p, v):             # a[p] = v\n    if l == r:\n        t[i] = v\n        return\n    m = (l + r) // 2\n    if p <= m:\n        update(2 * i, l, m, p, v)\n    else:\n        update(2 * i + 1, m + 1, r, p, v)\n    t[i] = t[2 * i] + t[2 * i + 1]     # tính lại trên đường về\n\na = [5, 2, 8, 6, 3, 7, 1, 4]\nn = len(a)\nt = [0] * (4 * n)\nbuild(1, 0, n - 1)\nprint(*t[1:16])"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a;\n    static long[] t;\n\n    static void Build(int i, int l, int r)\n    {\n        if (l == r) { t[i] = a[l]; return; }\n        int m = (l + r) / 2;\n        Build(2 * i, l, m);\n        Build(2 * i + 1, m + 1, r);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)   // tổng trên [x, y]\n    {\n        if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n        if (x <= l && r <= y) return t[i];                 // nằm trọn\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Update(int i, int l, int r, int p, int v)  // a[p] = v\n    {\n        if (l == r) { t[i] = v; return; }\n        int m = (l + r) / 2;\n        if (p <= m) Update(2 * i, l, m, p, v);\n        else Update(2 * i + 1, m + 1, r, p, v);\n        t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n    }\n\n    static void Main()\n    {\n        a = new[] { 5, 2, 8, 6, 3, 7, 1, 4 };\n        int n = a.Length;\n        t = new long[4 * n];\n        Build(1, 0, n - 1);\n        for (int i = 1; i < 16; i++) Console.Write(t[i] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Truy vấn tổng trên đoạn",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvector<int> a;\nvector<long long> t;\n\nvoid build(int i, int l, int r) {\n    if (l == r) { t[i] = a[l]; return; }\n    int m = (l + r) / 2;\n    build(2 * i, l, m);\n    build(2 * i + 1, m + 1, r);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {   // tổng trên [x, y]\n    if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n    if (x <= l && r <= y) return t[i];                 // nằm trọn\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nvoid update(int i, int l, int r, int p, int v) {      // a[p] = v\n    if (l == r) { t[i] = v; return; }\n    int m = (l + r) / 2;\n    if (p <= m) update(2 * i, l, m, p, v);\n    else update(2 * i + 1, m + 1, r, p, v);\n    t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n}\n\nint main() {\n    a = {5, 2, 8, 6, 3, 7, 1, 4};\n    int n = a.size();\n    t.assign(4 * n, 0);\n    build(1, 0, n - 1);\n    cout << query(1, 0, n - 1, 2, 6) << \"\\n\";   // 8 + 6 + 3 + 7 + 1\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"calls"}],py:{code:"def build(i, l, r):\n    if l == r:\n        t[i] = a[l]\n        return\n    m = (l + r) // 2\n    build(2 * i, l, m)\n    build(2 * i + 1, m + 1, r)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):              # tổng trên [x, y]\n    if y < l or r < x:                 # ngoài: phần tử trung hòa\n        return 0\n    if x <= l and r <= y:              # nằm trọn\n        return t[i]\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\ndef update(i, l, r, p, v):             # a[p] = v\n    if l == r:\n        t[i] = v\n        return\n    m = (l + r) // 2\n    if p <= m:\n        update(2 * i, l, m, p, v)\n    else:\n        update(2 * i + 1, m + 1, r, p, v)\n    t[i] = t[2 * i] + t[2 * i + 1]     # tính lại trên đường về\n\na = [5, 2, 8, 6, 3, 7, 1, 4]\nn = len(a)\nt = [0] * (4 * n)\nbuild(1, 0, n - 1)\nprint(query(1, 0, n - 1, 2, 6))         # 8 + 6 + 3 + 7 + 1"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a;\n    static long[] t;\n\n    static void Build(int i, int l, int r)\n    {\n        if (l == r) { t[i] = a[l]; return; }\n        int m = (l + r) / 2;\n        Build(2 * i, l, m);\n        Build(2 * i + 1, m + 1, r);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)   // tổng trên [x, y]\n    {\n        if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n        if (x <= l && r <= y) return t[i];                 // nằm trọn\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Update(int i, int l, int r, int p, int v)  // a[p] = v\n    {\n        if (l == r) { t[i] = v; return; }\n        int m = (l + r) / 2;\n        if (p <= m) Update(2 * i, l, m, p, v);\n        else Update(2 * i + 1, m + 1, r, p, v);\n        t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n    }\n\n    static void Main()\n    {\n        a = new[] { 5, 2, 8, 6, 3, 7, 1, 4 };\n        int n = a.Length;\n        t = new long[4 * n];\n        Build(1, 0, n - 1);\n        Console.WriteLine(Query(1, 0, n - 1, 2, 6));   // 8 + 6 + 3 + 7 + 1\n    }\n}"}},{label:"Ví dụ: Cập nhật một phần tử",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvector<int> a;\nvector<long long> t;\n\nvoid build(int i, int l, int r) {\n    if (l == r) { t[i] = a[l]; return; }\n    int m = (l + r) / 2;\n    build(2 * i, l, m);\n    build(2 * i + 1, m + 1, r);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {   // tổng trên [x, y]\n    if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n    if (x <= l && r <= y) return t[i];                 // nằm trọn\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nvoid update(int i, int l, int r, int p, int v) {      // a[p] = v\n    if (l == r) { t[i] = v; return; }\n    int m = (l + r) / 2;\n    if (p <= m) update(2 * i, l, m, p, v);\n    else update(2 * i + 1, m + 1, r, p, v);\n    t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n}\n\nint main() {\n    a = {5, 2, 8, 6, 3, 7, 1, 4};\n    int n = a.size();\n    t.assign(4 * n, 0);\n    build(1, 0, n - 1);\n    update(1, 0, n - 1, 3, 0);         // a[3] = 0\n    cout << t[1] << \" \" << query(1, 0, n - 1, 2, 6) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"calls"}],py:{code:"def build(i, l, r):\n    if l == r:\n        t[i] = a[l]\n        return\n    m = (l + r) // 2\n    build(2 * i, l, m)\n    build(2 * i + 1, m + 1, r)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):              # tổng trên [x, y]\n    if y < l or r < x:                 # ngoài: phần tử trung hòa\n        return 0\n    if x <= l and r <= y:              # nằm trọn\n        return t[i]\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\ndef update(i, l, r, p, v):             # a[p] = v\n    if l == r:\n        t[i] = v\n        return\n    m = (l + r) // 2\n    if p <= m:\n        update(2 * i, l, m, p, v)\n    else:\n        update(2 * i + 1, m + 1, r, p, v)\n    t[i] = t[2 * i] + t[2 * i + 1]     # tính lại trên đường về\n\na = [5, 2, 8, 6, 3, 7, 1, 4]\nn = len(a)\nt = [0] * (4 * n)\nbuild(1, 0, n - 1)\nupdate(1, 0, n - 1, 3, 0)              # a[3] = 0\nprint(t[1], query(1, 0, n - 1, 2, 6))"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a;\n    static long[] t;\n\n    static void Build(int i, int l, int r)\n    {\n        if (l == r) { t[i] = a[l]; return; }\n        int m = (l + r) / 2;\n        Build(2 * i, l, m);\n        Build(2 * i + 1, m + 1, r);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)   // tổng trên [x, y]\n    {\n        if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n        if (x <= l && r <= y) return t[i];                 // nằm trọn\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Update(int i, int l, int r, int p, int v)  // a[p] = v\n    {\n        if (l == r) { t[i] = v; return; }\n        int m = (l + r) / 2;\n        if (p <= m) Update(2 * i, l, m, p, v);\n        else Update(2 * i + 1, m + 1, r, p, v);\n        t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n    }\n\n    static void Main()\n    {\n        a = new[] { 5, 2, 8, 6, 3, 7, 1, 4 };\n        int n = a.Length;\n        t = new long[4 * n];\n        Build(1, 0, n - 1);\n        Update(1, 0, n - 1, 3, 0);             // a[3] = 0\n        Console.WriteLine(t[1] + \" \" + Query(1, 0, n - 1, 2, 6));\n    }\n}"}},{label:"Ví dụ: Cây min kèm vị trí",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvector<int> a;\nvector<pair<int,int>> t;               // {giá trị nhỏ nhất, vị trí}\n\nvoid build(int i, int l, int r) {\n    if (l == r) { t[i] = {a[l], l}; return; }\n    int m = (l + r) / 2;\n    build(2 * i, l, m);\n    build(2 * i + 1, m + 1, r);\n    t[i] = min(t[2 * i], t[2 * i + 1]);   // pair so giá trị trước, bằng thì vị trí nhỏ hơn\n}\n\npair<int,int> query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return {1000000000, -1};\n    if (x <= l && r <= y) return t[i];\n    int m = (l + r) / 2;\n    return min(query(2 * i, l, m, x, y), query(2 * i + 1, m + 1, r, x, y));\n}\n\nint main() {\n    a = {5, 2, 8, 2, 3, 7, 1, 4};\n    int n = a.size();\n    t.assign(4 * n, {0, 0});\n    build(1, 0, n - 1);\n    auto r1 = query(1, 0, n - 1, 1, 5);\n    cout << r1.first << \" o vi tri \" << r1.second << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"def build(i, l, r):\n    if l == r:\n        t[i] = (a[l], l)               # (giá trị, vị trí)\n        return\n    m = (l + r) // 2\n    build(2 * i, l, m)\n    build(2 * i + 1, m + 1, r)\n    t[i] = min(t[2 * i], t[2 * i + 1]) # tuple so giá trị trước, bằng thì vị trí nhỏ hơn\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return (float(\"inf\"), -1)\n    if x <= l and r <= y:\n        return t[i]\n    m = (l + r) // 2\n    return min(query(2 * i, l, m, x, y), query(2 * i + 1, m + 1, r, x, y))\n\na = [5, 2, 8, 2, 3, 7, 1, 4]\nn = len(a)\nt = [None] * (4 * n)\nbuild(1, 0, n - 1)\ngt, vt = query(1, 0, n - 1, 1, 5)\nprint(gt, \"o vi tri\", vt)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a, gt, vt;                // mỗi nút: giá trị nhỏ nhất gt[i] và vị trí vt[i]\n    static int kqG, kqV;                   // kết quả truy vấn đang gom\n\n    static void Gop(int i)                 // ghép hai con, bằng nhau thì lấy vị trí nhỏ hơn (con trái)\n    {\n        int L = 2 * i, R = 2 * i + 1;\n        if (gt[L] <= gt[R]) { gt[i] = gt[L]; vt[i] = vt[L]; }\n        else { gt[i] = gt[R]; vt[i] = vt[R]; }\n    }\n\n    static void Build(int i, int l, int r)\n    {\n        if (l == r) { gt[i] = a[l]; vt[i] = l; return; }\n        int m = (l + r) / 2;\n        Build(2 * i, l, m);\n        Build(2 * i + 1, m + 1, r);\n        Gop(i);\n    }\n\n    static void Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y)\n        {\n            if (gt[i] < kqG) { kqG = gt[i]; kqV = vt[i]; }   // duyệt trái trước: bằng nhau giữ vị trí cũ (nhỏ hơn)\n            return;\n        }\n        int m = (l + r) / 2;\n        Query(2 * i, l, m, x, y);\n        Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Main()\n    {\n        a = new[] { 5, 2, 8, 2, 3, 7, 1, 4 };\n        int n = a.Length;\n        gt = new int[4 * n];\n        vt = new int[4 * n];\n        Build(1, 0, n - 1);\n        kqG = int.MaxValue;\n        kqV = -1;\n        Query(1, 0, n - 1, 1, 5);\n        Console.WriteLine(kqG + \" o vi tri \" + kqV);\n    }\n}",note:"C# trong trình mô phỏng chưa có tuple, nên mỗi nút giữ hai mảng song song: gt (giá trị) và vt (vị trí). Trên [1, 5] giá trị nhỏ nhất 2 xuất hiện ở vị trí 1 và 3; chọn vị trí nhỏ hơn: 1."}},{label:"Lỗi: cấp mảng 2n ô",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvector<int> a;\nvector<long long> t;\n\nvoid build(int i, int l, int r) {\n    if (l == r) { t[i] = a[l]; return; }\n    int m = (l + r) / 2;\n    build(2 * i, l, m);\n    build(2 * i + 1, m + 1, r);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {   // tổng trên [x, y]\n    if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n    if (x <= l && r <= y) return t[i];                 // nằm trọn\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nvoid update(int i, int l, int r, int p, int v) {      // a[p] = v\n    if (l == r) { t[i] = v; return; }\n    int m = (l + r) / 2;\n    if (p <= m) update(2 * i, l, m, p, v);\n    else update(2 * i + 1, m + 1, r, p, v);\n    t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n}\n\nint main() {\n    a = {1, 2, 3, 4, 5, 6};\n    int n = a.size();\n    t.assign(2 * n, 0);                // SAI: cần 4n\n    build(1, 0, n - 1);\n    cout << t[1] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"calls"}],py:{code:"def build(i, l, r):\n    if l == r:\n        t[i] = a[l]\n        return\n    m = (l + r) // 2\n    build(2 * i, l, m)\n    build(2 * i + 1, m + 1, r)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):              # tổng trên [x, y]\n    if y < l or r < x:                 # ngoài: phần tử trung hòa\n        return 0\n    if x <= l and r <= y:              # nằm trọn\n        return t[i]\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\ndef update(i, l, r, p, v):             # a[p] = v\n    if l == r:\n        t[i] = v\n        return\n    m = (l + r) // 2\n    if p <= m:\n        update(2 * i, l, m, p, v)\n    else:\n        update(2 * i + 1, m + 1, r, p, v)\n    t[i] = t[2 * i] + t[2 * i + 1]     # tính lại trên đường về\n\na = [1, 2, 3, 4, 5, 6]\nn = len(a)\nt = [0] * (2 * n)                      # SAI: cần 4n\nbuild(1, 0, n - 1)\nprint(t[1])",note:"Với n = 6 cây không đầy: nút 13 (quản lý [4, 4]) có số hiệu vượt 2n = 12: IndexError. Luôn cấp 4n ô."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a;\n    static long[] t;\n\n    static void Build(int i, int l, int r)\n    {\n        if (l == r) { t[i] = a[l]; return; }\n        int m = (l + r) / 2;\n        Build(2 * i, l, m);\n        Build(2 * i + 1, m + 1, r);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)   // tổng trên [x, y]\n    {\n        if (y < l || r < x) return 0;                      // ngoài: phần tử trung hòa\n        if (x <= l && r <= y) return t[i];                 // nằm trọn\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Update(int i, int l, int r, int p, int v)  // a[p] = v\n    {\n        if (l == r) { t[i] = v; return; }\n        int m = (l + r) / 2;\n        if (p <= m) Update(2 * i, l, m, p, v);\n        else Update(2 * i + 1, m + 1, r, p, v);\n        t[i] = t[2 * i] + t[2 * i + 1];                    // tính lại trên đường về\n    }\n\n    static void Main()\n    {\n        a = new[] { 1, 2, 3, 4, 5, 6 };\n        int n = a.Length;\n        t = new long[2 * n];                   // SAI: cần 4n\n        Build(1, 0, n - 1);\n        Console.WriteLine(t[1]);\n    }\n}",note:"Với n = 6 cây không đầy: nút 13 (quản lý [4, 4]) có số hiệu vượt 2n = 12: IndexOutOfRangeException. Luôn cấp 4n ô."}}];
